def shortest_edit_script(a: list[str], b: list[str]) -> list[tuple]:
    n = len(a)
    m = len(b)

    ids: dict[str, int] = {}
    a2: list[int] = []
    for x in a:
        idx = ids.get(x)
        if idx is None:
            idx = len(ids)
            ids[x] = idx
        a2.append(idx)

    b2: list[int] = []
    masks: dict[int, int] = {}
    bit = 1
    for x in b:
        idx = ids.get(x)
        if idx is None:
            idx = len(ids)
            ids[x] = idx
        b2.append(idx)
        masks[idx] = masks.get(idx, 0) | bit
        bit <<= 1

    v = 0
    for x in a2:
        xmask = masks.get(x, 0)
        x = v | xmask
        y = (v << 1) | 1
        v = x & ~(x - y)

    lcs_len = v.bit_count()
    dist = n + m - 2 * lcs_len

    width = 2 * dist + 1
    inf = 10 ** 9
    rows: list[list[int] | None] = [None] * (n + 1)

    row = [inf] * width
    for d in range(-dist, dist + 1):
        j = n - d
        if 0 <= j <= m:
            row[dist + d] = m - j
        elif j < 0:
            break
    rows[n] = row

    for i in range(n - 1, -1, -1):
        cur = [inf] * width
        nxt = rows[i + 1]
        ai = a2[i]

        for d in range(-dist, dist + 1):
            j = i - d
            if j < 0:
                break
            if j > m:
                continue

            best = inf

            if j < m and ai == b2[j]:
                val = nxt[dist + d]
                if val < best:
                    best = val

            if d < dist:
                val = nxt[dist + d + 1]
                if val + 1 < best:
                    best = val + 1

            if j < m and d > -dist:
                val = cur[dist + d - 1]
                if val + 1 < best:
                    best = val + 1

            cur[dist + d] = best

        rows[i] = cur

    script: list[tuple] = []
    i = j = 0
    r = rows[0][dist]

    while i < n or j < m:
        d = i - j

        if i < n and j < m and a2[i] == b2[j]:
            if -dist <= d <= dist:
                nr = rows[i + 1][dist + d]
                if nr == r:
                    script.append(("=", i, j))
                    i += 1
                    j += 1
                    continue

        if i < n:
            nd = d + 1
            if -dist <= nd <= dist:
                nr = rows[i + 1][dist + nd]
                if nr == r - 1:
                    script.append(("-", i))
                    i += 1
                    r -= 1
                    continue

        if j < m:
            nd = d - 1
            if -dist <= nd <= dist:
                nr = rows[i][dist + nd]
                if nr == r - 1:
                    script.append(("+", j))
                    j += 1
                    r -= 1
                    continue

        break

    return script
